package io.github.henriquevmdev.erpconnector.testkit;

/**
 * CPF numbers for test fixtures, generated by the check-digit algorithm from a counter, never copied from real
 * documents (AGENTS.md, hard rule 1). Implemented here on its own, not by calling {@code core}, so the suite does not
 * check the library's validator against itself.
 */
public final class SyntheticDocuments {

    /** A CPF with correct check digits, unmasked. Different {@code n} give different numbers. */
    public static String validCpf(int n) {
        if (n < 0 || n > 899_999_999) {
            throw new IllegalArgumentException("n out of range");
        }
        int[] d = new int[11];
        String base = Integer.toString(100_000_000 + n);
        for (int i = 0; i < 9; i++) {
            d[i] = base.charAt(i) - '0';
        }
        d[9] = checkDigit(d, 9);
        d[10] = checkDigit(d, 10);
        StringBuilder cpf = new StringBuilder(11);
        for (int digit : d) {
            cpf.append(digit);
        }
        return cpf.toString();
    }

    /** {@link #validCpf(int)} with the last check digit changed, so validation must fail. */
    public static String invalidCpf(int n) {
        String valid = validCpf(n);
        int last = valid.charAt(10) - '0';
        return valid.substring(0, 10) + (last + 1) % 10;
    }

    private static int checkDigit(int[] d, int length) {
        int sum = 0;
        for (int i = 0; i < length; i++) {
            sum += d[i] * (length + 1 - i);
        }
        int remainder = sum % 11;
        return remainder < 2 ? 0 : 11 - remainder;
    }

    private SyntheticDocuments() {
    }
}
